<template>
  <div ref="anchor" class="design-plate-anchor" :style="expanded ? { height: `${inlineHeight}px` } : null" @pointerenter="hovered = true" @pointerleave="hovered = false">
    <dialog ref="dialog" class="design-plate" :class="{ 'is-expanded': expanded, 'is-animating': animating, 'is-floor-plan': feature.id === 'orientation', 'is-building': feature.id === 'building' }" :aria-label="feature.title" :role="expanded ? 'dialog' : 'group'" @cancel.prevent="close" @close="restore" @click="onBackdrop" @keydown.stop>
      <div v-if="expanded" ref="scrim" class="design-plate-scrim" aria-hidden="true" @click="close" />
      <header v-if="expanded" ref="head" class="design-plate-head">
        <span>{{ feature.title }}</span>
        <button type="button" class="design-plate-close" aria-label="Close design detail" autofocus @click="close"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg></button>
      </header>
      <div ref="visual" class="design-plate-visual">
        <div class="design-plate-art" :class="{ 'is-hovered': hovered && !expanded }">
