          <MuseumFloorPlan v-else-if="feature.id === 'orientation'" presentation :overview="!expanded" :show-discovery-cue="false" :dark="dark" />
          <GalleryBuildingMark detailed v-else-if="feature.id === 'building'" :interactive="expanded" :active="hovered && !expanded" :dark="dark" />
