<script>
import ViewGalleryLiveStage from './ViewGalleryLiveStage.vue';
import MuseumFloorPlan from '../view/MuseumFloorPlan.vue';
import GalleryBuildingMark from './GalleryBuildingMark.vue';
import GalleryLightComparison from './GalleryLightComparison.vue';
import { lockBodyScroll } from '../../utils/bodyScrollLock';
const ease = 'cubic-bezier(.22,1,.36,1)';
export default {
  components: { GalleryBuildingMark, GalleryLightComparison, ViewGalleryLiveStage, MuseumFloorPlan },
  props: { feature: { type: Object, required: true }, number: Number, dark: Boolean },
  data: () => ({ expanded: false, hovered: false, animating: false, inlineHeight: 0, demoPaused: false }),
  mounted() { window.addEventListener('hashchange', this.close); },
  beforeUnmount() { this._unmounted = true; window.removeEventListener('hashchange', this.close); this.cancelAnimations(); this._release?.(); },
  methods: {
    motionNode() { return this.feature.id === 'orientation' ? this.$refs.visual.querySelector('.museum-floor-plan') : this.$refs.visual; },
    fadeParts() { return [this.$refs.head, this.$refs.copy, this.feature.id === 'orientation' && this.$refs.visual.querySelector('.plan-detail')].filter(Boolean); },
    image(dark) { return `/assets/img/projects/gallery-experience/${this.feature.image}-${dark ? 'dark' : 'light'}.webp?v=20260925`; },
    transform(from, to) { return `translate(${from.left-to.left}px,${from.top-to.top}px) scale(${from.width/to.width},${from.height/to.height})`; },
    cancelAnimations() { this._animations?.forEach(animation => animation.cancel()); this._animations = []; },
    animate(element, frames, duration) { const animation = element.animate(frames, { duration: this._still ? 0 : duration, easing: ease, fill: 'both' }); this._animations.push(animation); return animation; },
    async open(event) {
      if (this.expanded) return;
