      this.animate(this.$refs.scrim, [{ opacity: 0 }, { opacity: 1 }], 300);
      for (const element of this.fadeParts()) this.animate(element, [{ opacity: 0, transform: 'translateY(8px)', offset: 0 }, { opacity: 0, transform: 'translateY(8px)', offset: .3 }, { opacity: 1, transform: 'none' }], 360);
      await zoom.finished.catch(() => {});
      if (!this._closing && !this._unmounted) { this.animating = false; this.$refs.dialog.querySelector('.design-plate-close')?.focus({ preventScroll: true }); }
    },
    async close() {
      if (!this.expanded || !this.$refs.dialog?.open || this._closing) return;
