      this.cancelAnimations();
      const full = this.motionNode().getBoundingClientRect();
      const anchor = this.$refs.anchor.getBoundingClientRect();
      let origin = { left: anchor.left, top: anchor.top, width: anchor.width, height: anchor.width * 1046 / 1920 };
      if (this.feature.id === 'orientation') {
        const padding = matchMedia('(max-width:640px)').matches ? 5 : 14;
        const height = origin.height - padding * 2, width = height * 42 / 36;
        origin = { left:anchor.left+(anchor.width-width)/2, top:anchor.top+padding, width, height };
