      if (!this.expanded) return;
      this.cancelAnimations(); this.expanded = false; this.animating = false; this._closing = false;
      this._release?.(); this._release = null;
      await this.$nextTick();
      if (!this._unmounted) this.$refs.trigger?.focus({ preventScroll: true });
    },
    onBackdrop(event) { if (event.target === this.$refs.dialog) this.close(); },
  },
};
</script>
