<template>
  <div class="translation-control">
    <button ref="trigger" class="translation-action" type="button" :aria-label="visible ? `Reading in ${label(target)}. Choose language` : 'Choose reading language'" aria-haspopup="dialog" :aria-expanded="opened" @click="open">
      <svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="7.1"/><path d="M3 10h14M10 3c-4 4-4 10 0 14 4-4 4-10 0-14Z"/></svg>
      <span>{{ loading ? 'Translating…' : visible ? label(target) : source ? label(source) : 'Language' }}</span><svg class="language-chevron" viewBox="0 0 12 12" aria-hidden="true"><path d="m3 5 3 3 3-3"/></svg>
    </button>
    <span v-if="error" class="translation-status" role="status">{{ error }}</span>
    <Teleport to="body">
      <dialog v-if="opened" ref="menu" class="view-language-menu" :style="position" aria-label="Choose reading language" @cancel.prevent="close" @keydown.stop>
        <header><span>Read in</span><button type="button" aria-label="Close language menu" @click="close">×</button></header>
        <input ref="search" v-model="query" type="search" placeholder="Find a language" aria-label="Find a language" @keydown.down.prevent="$refs.options?.querySelector('button')?.focus()">
        <div ref="options" class="language-options">
          <button v-if="!query" type="button" :aria-pressed="!visible" @click="select('')"><span>Original<small v-if="source">{{ label(source) }}</small></span><span v-if="!visible" aria-hidden="true">✓</span></button>
          <button v-if="!query && suggested" type="button" :aria-pressed="visible && target === preferred" @click="select(preferred)"><span>{{ label(preferred) }}<small>Browser language</small></span><span v-if="visible && target === preferred" aria-hidden="true">✓</span></button>
          <div v-if="!query" class="language-rule"></div>
          <button v-for="language in filtered" :key="language.language" type="button" :aria-pressed="visible && target === language.language" @click="select(language.language)"><span>{{ label(language.language) }}<small v-if="label(language.language) !== language.name">{{ language.name }}</small></span><span v-if="visible && target === language.language" aria-hidden="true">✓</span></button>
          <p v-if="!filtered.length">{{ listLoading ? 'Loading languages…' : 'No matching language' }}</p>
        </div>
      </dialog>
    </Teleport>
  </div>
</template>
<script>
import { languageName, sameViewLanguage, systemViewLanguage } from '../../utils/viewLanguages';
import { getViewLanguages } from '../../utils/viewShareSite';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';
const FALLBACK = ['en','zh-CN','zh-TW','ja','ko','fr','de','es','it','pt','ar','hi','ru','uk','nl','pl','sv','da','no','fi','el','tr','vi','th','id','ms','he','fa','bn','ta','ur'];
let languagePromise;
export default {
  props: { loading: Boolean, visible: Boolean, loaded: Boolean, error: { type: String, default: '' }, source: { type: String, default: '' }, target: { type: String, default: 'en' } },
  emits: ['select'],
  data: () => ({ opened: false, query: '', position: {}, listLoading: false, languages: FALLBACK.map(language => ({ language, name: languageName(language, 'en') })), preferred: systemViewLanguage(navigator.languages) }),
  computed: {
    suggested() { return !!this.source && !sameViewLanguage(this.source, this.preferred); },
    filtered() { const q = this.query.trim().toLocaleLowerCase(); return this.languages.filter(item => [item.name,item.language,this.label(item.language)].some(text => text.toLocaleLowerCase().includes(q))).sort((a,b) => a.name.localeCompare(b.name)); },
  },
  beforeUnmount() { this._stopBackdrop?.(); this.$refs.menu?.close(); },
  methods: {
    label(code) { const name = languageName(code); return name === code ? this.languages.find(item => item.language === code)?.name || code : name; },
    async open() {
      if (this.opened) { this.close(); return; }
      const rect = this.$refs.trigger.getBoundingClientRect(), width = Math.min(270, innerWidth - 24), height = Math.min(420, innerHeight - 32);
      this.position = { left: `${Math.min(innerWidth - width - 12, Math.max(12, rect.left))}px`, top: `${Math.max(12, Math.min(innerHeight - height - 12, rect.bottom + 9))}px`, width: `${width}px`, maxHeight: `${height}px` };
      this.query = ''; this.opened = true; await this.$nextTick(); this.$refs.menu.showModal();
      this._stopBackdrop = initDialogBackdrop(this.$refs.menu, this.close); this.$refs.search.focus({ preventScroll: true });
      this.listLoading = true;
      try { if (!languagePromise) languagePromise = getViewLanguages().catch(error => { languagePromise = null; throw error; }); const result = await languagePromise; this.languages = result.languages; }
      catch { /* The common language list remains usable during an outage. */ }
      finally { this.listLoading = false; }
    },
    close() { this._stopBackdrop?.(); this.$refs.menu?.close(); this.opened = false; this.$refs.trigger?.focus({ preventScroll: true }); },
    select(language) { this.$emit('select', language); this.close(); },
  },
};
</script>
<style scoped>
.translation-control { display: inline-flex; align-items: center; gap: 5px; position: relative; font-family: 'Quattrocento Sans',sans-serif; color: var(--view-muted,var(--ex-muted,#777)); }
.translation-action, .translation-suggestion { appearance: none; display: inline-flex; align-items: center; gap: 5px; border: 0; background: transparent; color: inherit; font: 11px/1.3 'Quattrocento Sans',sans-serif; padding: 4px 2px; cursor: var(--site-interactive-cursor); }
.translation-action { min-width: 24px; min-height: 26px; justify-content: center; }
.translation-action:hover, .translation-suggestion:hover { color: var(--view-ink,var(--ex-ink,#333)); }
.translation-action svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.1; stroke-linecap: round; stroke-linejoin: round; }
.translation-action .language-chevron { width: 10px; height: 10px; }
.translation-action:focus-visible, .translation-suggestion:focus-visible { outline: 1px solid currentColor; outline-offset: 3px; }
.translation-suggestion:disabled { opacity: .55; }
.translation-status { position: absolute; top: 100%; min-width: 180px; font-size: 11px; }
.view-language-menu { box-sizing: border-box; position: fixed; margin: 0; padding: 12px; color: #393b35; background: #fffffff5; border: 1px solid #30383024; border-radius: 11px; box-shadow: 0 12px 40px #0002; backdrop-filter: blur(18px); overflow: hidden; font: 13px/1.4 'Quattrocento Sans',sans-serif; }
.view-language-menu[open] { display: flex; flex-direction: column; animation: language-appear 160ms ease-out; }
.view-language-menu::backdrop { background: transparent; }
.view-language-menu header { display: flex; align-items: center; justify-content: space-between; padding: 2px 3px 10px; }
.view-language-menu button { appearance: none; color: inherit; font: inherit; border: 0; background: none; cursor: var(--site-interactive-cursor); }
.view-language-menu header button { width: 25px; height: 25px; font-size: 20px; }
.view-language-menu input { box-sizing: border-box; width: 100%; border: 1px solid #8883; border-radius: 5px; padding: 8px 10px; background: #8881; color: inherit; font: inherit; cursor: var(--site-text-cursor); }
.language-options { overflow-y: auto; min-height: 0; margin: 8px -3px -3px; overscroll-behavior: contain; }
.language-options button { display: flex; align-items: center; justify-content: space-between; text-align: left; width: 100%; padding: 8px 9px; border-radius: 4px; }
.language-options button:hover, .language-options button:focus-visible { background: #8882; outline: none; }
.language-options small { display: block; opacity: .55; font-size: 10px; margin-top: 1px; }
.language-options p { padding: 8px; font-size: 12px; opacity: .65; }
.language-rule { border-top: 1px solid #8883; margin: 5px 8px; }
:global(body.dark-mode .view-language-menu) { color: #e4e1d9; background: #262825f5; border-color: #d8d8cc28; }
@keyframes language-appear { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: translateY(0); } }
@media(prefers-reduced-motion:reduce) { .view-language-menu[open] { animation: none; } }
</style>
