<script>
import { activityEnabled, setActivityPreference } from '../../utils/siteActivity';
import { lockBodyScroll } from '../../utils/bodyScrollLock';
import GalleryMark from './GalleryMark.vue';
import AiViewTerm from '../ui/AiViewTerm.vue';
import ViewAboutContent from './ViewAboutContent.vue';
import MuseumFloorPlan from './MuseumFloorPlan.vue';
import GalleryProjectLink from './GalleryProjectLink.vue';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';

export default {
  name: 'PublicViewsInfoDialog',
  components: { GalleryMark, AiViewTerm, ViewAboutContent, MuseumFloorPlan, GalleryProjectLink },
  props: { note: Boolean, museum: Boolean, centred: Boolean, dark: Boolean, area: {type:String,default:'hall'}, tourAvailable: { type: Boolean, default: true } },
  emits: ['close','tour','navigate'],
  data:()=>({viewportStyle:{},closing:false,analyticsOn:activityEnabled()}),
  methods:{
    toggleActivity(){this.analyticsOn=!this.analyticsOn;setActivityPreference(this.analyticsOn);},
    async leave(event='close',payload){
      if(this.closing)return;
      this.closing=true;
      if(this.museum&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
        const opacity=getComputedStyle(this.$refs.dialog).opacity;
        this._entrance?.cancel();
        this._exit=this.$refs.dialog.animate([{opacity},{opacity:0}],{duration:320,easing:'ease-in-out',fill:'forwards'});
        await this._exit.finished.catch(()=>{});
      }
      if(!this._destroyed)this.$emit(event,payload);
    },
    syncViewport(){const v=window.visualViewport,w=v?.width||window.innerWidth,h=v?.height||window.innerHeight;this.viewportStyle={'--dialog-centre-x':`${(v?.offsetLeft||0)+w/2}px`,'--dialog-centre-y':`${(v?.offsetTop||0)+h/2}px`,'--dialog-height':`${h}px`,'--dialog-width':`${w}px`};}},
  mounted() {
    this.syncViewport();
    this._viewport=window.visualViewport;
    this._viewport?.addEventListener('resize',this.syncViewport);this._viewport?.addEventListener('scroll',this.syncViewport);window.addEventListener('resize',this.syncViewport);
    this._trigger = document.activeElement;
    this._releaseScroll = lockBodyScroll();
    this.$refs.dialog.showModal();
    if (this.museum && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
      this._entrance = this.$refs.dialog.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 400, easing: 'ease-out' });
    }
    this._stopBackdrop = initDialogBackdrop(this.$refs.dialog, () => this.leave('close'));
    this.$refs.close.focus({ preventScroll: true });
  },
  beforeUnmount() {
    this._destroyed=true;this._exit?.cancel();
    this._viewport?.removeEventListener('resize',this.syncViewport);this._viewport?.removeEventListener('scroll',this.syncViewport);window.removeEventListener('resize',this.syncViewport);
    this._entrance?.cancel();
    this._stopBackdrop?.();
    this.$refs.dialog?.close();
    this._releaseScroll?.();
    if (this._trigger?.isConnected) this._trigger.focus({ preventScroll: true });
  },
};
</script>

